(function(root){
'use strict';
const names={john:'Джон',james:'Джеймс',michael:'Майкл',william:'Уильям',isaac:'Айзек',phillips:'Филлипс',lucie:'Люси',lucy:'Люси',leo:'Лео',léo:'Лео',jean:'Жан',pierre:'Пьер',louis:'Луи',louise:'Луиза',ethan:'Итан',noah:'Ноа',emma:'Эмма',esther:'Эстер',ana:'Ана',rafael:'Рафаэл',david:'Давид',sarah:'Сара',marie:'Мари',alice:'Алиса',george:'Джордж',charles:'Чарльз',henry:'Генри',robert:'Роберт',thomas:'Томас',smith:'Смит',brown:'Браун',jones:'Джонс',williams:'Уильямс',maria:'Мария',anna:'Анна',anna:'Анна'};
const letters={a:'а',b:'б',c:'к',d:'д',e:'е',f:'ф',g:'г',h:'х',i:'и',j:'дж',k:'к',l:'л',m:'м',n:'н',o:'о',p:'п',q:'к',r:'р',s:'с',t:'т',u:'у',v:'в',w:'в',x:'кс',y:'й',z:'з'};
const clusters={sch:'ш',tch:'ч',sh:'ш',ch:'ч',zh:'ж',kh:'х',th:'т',ph:'ф',qu:'кв',ck:'к',ng:'нг',oo:'у',ee:'и',ou:'у',ai:'ай',ay:'эй',oy:'ой',ya:'я',yu:'ю',yo:'ё',je:'же',ll:'ль'};
function word(value){const key=value.toLowerCase(),clean=key.normalize('NFD').replace(/[\u0300-\u036f]/g,'');let out=names[key]||names[clean];if(!out){out='';for(let i=0;i<clean.length;){const cluster=[3,2].map(n=>clean.slice(i,i+n)).find(s=>clusters[s]);if(cluster){out+=clusters[cluster];i+=cluster.length;}else {out+=letters[clean[i]]||clean[i];i++;} }}return value[0]===value[0].toUpperCase()?out[0]?.toUpperCase()+out.slice(1):out.toLowerCase();}
// Non-Latin scripts are transliterated by the upstream name tables; keep identifiers and URLs out of this display-only function.
function text(value){let s=String(value??'');s=s.replace(/Unavailable (?:choice|action|focus|policy|setting|investment)/g,'Этот выбор сейчас недоступен').replace(/Surname is fixed/g,'Фамилию сейчас нельзя изменить').replace(/World Bank/gi,'Всемирный банк').replace(/1in8b(?:\.life)?/gi,'').replace(/\bPPP\b/g,'').replace(/(?:по российским ценам|в пересчёте на российские цены|корейский эквивалент)/gi,'в долларах США').replace(/\bUSD\b/g,'долл. США').replace(/\bOECD\b/g,'ОЭСР').replace(/\bILO(?:STAT)?\b/g,'МОТ').replace(/\bWHO\b/g,'ВОЗ').replace(/\bUNICEF\b/g,'ЮНИСЕФ').replace(/\bGDP\b/g,'ВВП').replace(/\bHIV\b/g,'ВИЧ').replace(/\bAIDS\b/g,'СПИД').replace(/\bCOVID(?:-19)?\b/g,'ковид').replace(/\b(?:DHS|CDC|UN|UNDP)\b/g,x=>({DHS:'демографические обследования',CDC:'Центры контроля заболеваний',UN:'ООН',UNDP:'ПРООН'}[x]));s=s.replace(/[A-Za-zÀ-ž]+(?:['’][A-Za-zÀ-ž]+)*/g,word);return s.replace(/\s+\)/g,')').trim();}
const api={text,word};root.LifelineRussian=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
